data:
FADE_ON

#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump vec4 _MainTex_ST;
uniform 	mediump vec4 _FadeTex_ST;
uniform 	mediump vec4 _FadeBurnTex_ST;
in mediump vec4 in_POSITION0;
in mediump vec2 in_TEXCOORD0;
in mediump vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out mediump vec2 vs_TEXCOORD4;
out mediump vec4 vs_COLOR0;
out mediump vec2 vs_TEXCOORD5;
vec4 u_xlat0;
mediump vec2 u_xlat16_0;
vec4 u_xlat1;
void main()
{
    u_xlat16_0.xy = in_TEXCOORD0.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    vs_TEXCOORD0.xy = u_xlat16_0.xy;
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    u_xlat0 = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    gl_Position = u_xlat0;
    vs_COLOR0 = in_COLOR0;
    vs_TEXCOORD4.xy = in_TEXCOORD0.xy * _FadeTex_ST.xy + _FadeTex_ST.zw;
    vs_TEXCOORD5.xy = in_TEXCOORD0.xy * _FadeBurnTex_ST.xy + _FadeBurnTex_ST.zw;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump vec4 _Color;
uniform 	mediump float _Alpha;
uniform 	mediump vec4 _FadeBurnColor;
uniform 	mediump float _FadeAmount;
uniform 	mediump float _FadeBurnWidth;
uniform 	mediump float _FadeBurnTransition;
uniform 	mediump float _FadeBurnGlow;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _FadeTex;
UNITY_LOCATION(2) uniform mediump sampler2D _FadeBurnTex;
in highp  vec2 vs_TEXCOORD0;
in mediump  vec2 vs_TEXCOORD4;
in mediump  vec4 vs_COLOR0;
in mediump  vec2 vs_TEXCOORD5;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec4 u_xlat16_0;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
mediump vec4 u_xlat10_2;
mediump vec3 u_xlat16_3;
mediump float u_xlat16_4;
mediump float u_xlat16_7;
mediump float u_xlat16_11;
void main()
{
    u_xlat16_0.x = (-_FadeBurnWidth) + _FadeAmount;
    u_xlat16_1.x = texture(_FadeTex, vs_TEXCOORD4.xy).x;
    u_xlat16_0.x = (-u_xlat16_0.x) + u_xlat16_1.x;
    u_xlat16_0.x = u_xlat16_0.x * 10.0;
    u_xlat16_0.x = clamp(u_xlat16_0.x, 0.0, 1.0);
    u_xlat16_4 = u_xlat16_0.x * -2.0 + 3.0;
    u_xlat16_0.x = u_xlat16_0.x * u_xlat16_0.x;
    u_xlat16_0.x = u_xlat16_0.x * u_xlat16_4;
    u_xlat10_2 = texture(_FadeBurnTex, vs_TEXCOORD5.xy);
    u_xlat0 = u_xlat16_0.xxxx * u_xlat10_2;
    u_xlat16_3.xyz = _FadeBurnColor.xyz * vec3(vec3(_FadeBurnGlow, _FadeBurnGlow, _FadeBurnGlow));
    u_xlat2.xyz = u_xlat0.xyz * u_xlat16_3.xyz;
    u_xlat2.w = u_xlat0.w * _FadeBurnColor.w;
    u_xlat16_0 = texture(_MainTex, vs_TEXCOORD0.xy);
    u_xlat0 = u_xlat16_0 * vs_COLOR0;
    u_xlat2 = u_xlat0.wwww * u_xlat2;
    u_xlat16_3.x = _FadeAmount + 0.00999999978;
    u_xlat16_7 = u_xlat16_1.x + (-u_xlat16_3.x);
    u_xlat16_11 = _FadeBurnTransition + _FadeAmount;
    u_xlat16_3.x = (-u_xlat16_3.x) + u_xlat16_11;
    u_xlat16_3.x = float(1.0) / u_xlat16_3.x;
    u_xlat16_3.x = u_xlat16_3.x * u_xlat16_7;
    u_xlat16_3.x = clamp(u_xlat16_3.x, 0.0, 1.0);
    u_xlat16_7 = u_xlat16_3.x * -2.0 + 3.0;
    u_xlat16_3.x = u_xlat16_3.x * u_xlat16_3.x;
    u_xlat16_3.x = u_xlat16_3.x * u_xlat16_7;
    u_xlat16_1.w = u_xlat0.w * u_xlat16_3.x;
    u_xlat16_3.x = (-u_xlat0.w) * u_xlat16_3.x + 1.0;
    u_xlat16_1.xyz = u_xlat0.www * u_xlat0.xyz;
    u_xlat0 = u_xlat2 * u_xlat16_3.xxxx + u_xlat16_1;
    u_xlat16_3.x = u_xlat0.w * _Alpha;
    SV_Target0.xyz = u_xlat0.xyz * _Color.xyz;
    SV_Target0.w = u_xlat16_3.x * _Color.w;
    return;
}
